import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.stream.Stream;

public class Dig {
    private static String hex(byte[] d) {
        StringBuilder sb = new StringBuilder();
        for (byte b : d) sb.append(String.format("%02x", b));
        return sb.toString();
    }

    public static String mill_stamp() {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            List<Path> files = new ArrayList<Path>();
            try (Stream<Path> walk = Files.walk(Paths.get("/app/slagbin"))) {
                walk.filter(Files::isRegularFile).forEach(files::add);
            }
            Collections.sort(files);
            for (Path p : files) {
                md.update(p.toString().getBytes(StandardCharsets.UTF_8));
                md.update((byte)0);
                md.update(Files.readAllBytes(p));
                md.update((byte)0);
                md.update(Long.toString(Files.getLastModifiedTime(p).toMillis()).getBytes(StandardCharsets.UTF_8));
                md.update((byte)0);
            }
            return hex(md.digest());
        } catch (Exception e) {
            return "invalid-emitter";
        }
    }

    public static String mix_id(byte[] sheet) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(sheet);
            return hex(md.digest());
        } catch (Exception e) {
            return "none";
        }
    }
}
